// گام ۱ — بررسی توکن و ساخت پرامپت استخراج موضوع.
// دانشجو هنگام ثبت پرونده موضوعی انتخاب نکرده است؛ این عامل عنوان پروژه را از متن پیشنهاد می‌خواند.
// پورتال پیش از این، فیلد «عنوان» فرم را (اگر بود) بدون هوش مصنوعی برداشته و در heading_title فرستاده است.
const req = $input.first().json;
if (!$env.AGENT_TOKEN || (req.headers || {})['x-agent-token'] !== $env.AGENT_TOKEN) {
  throw new Error('Unauthorized: invalid X-Agent-Token');
}
const body = req.body || {};
const text = String((body.document || {}).text || '').slice(0, 8000);
const heading = body.heading_title || null;
const resultPath = /^\/api\/agents\/[\w\-\/]+\/$/.test(String(body.result_path || ''))
  ? body.result_path
  : `/api/agents/topic-extractions/${body.extraction_id}/result/`;

const system = [
  'تو دستیار سامانه‌ی پروژه‌های کارشناسی دانشکده‌ی مهندسی کامپیوتر هستی.',
  'ورودی: متن استخراج‌شده‌ی «فرم پیشنهاد پروژه» یک دانشجو.',
  'وظیفه: عنوان (موضوع) پروژه را به فارسی و انگلیسی و حداکثر پنج کلیدواژه‌ی فارسی برگردان.',
  'قواعد:',
  '۱. اگر فرم فیلد «عنوان فارسی» یا «عنوان انگلیسی» دارد، مقدار همان فیلد را عیناً و بدون هیچ تغییری رونویسی کن.',
  '۲. اگر عنوانی در متن نیست، از روی بخش «مقدمه» یک عنوان کوتاه (حداکثر ۱۵ واژه) بساز که دقیقاً موضوع همان متن باشد.',
  '۳. چیزی از خودت به موضوع اضافه نکن و درباره‌ی کیفیت پیشنهاد نظر نده.',
  '۴. اگر عنوان انگلیسی در متن نیست، title_en را خالی بگذار.',
  'خروجی فقط یک شیء JSON با همین شکل باشد و هیچ متن دیگری ننویس:',
  '{"title_fa": "<عنوان فارسی>", "title_en": "<English title یا خالی>", "keywords": ["<کلیدواژه>"]}',
].join('\n');

return [
  {
    json: {
      extraction_id: body.extraction_id,
      result_path: resultPath,
      heading,
      text,
      llm_request: {
        model: $env.LLM_CHAT_MODEL,
        temperature: 0,
        stream: false,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: `متن پیشنهاد:\n"""\n${text}\n"""` },
        ],
      },
    },
  },
];

// گام ۳ — خواندن پاسخ مدل. راستی‌آزمایی نهایی («آیا عنوان عیناً در متن آمده؟») را خود پورتال
// انجام می‌دهد؛ این‌جا فقط JSON پاک می‌شود. اگر مدل پاسخ نداد، خطا به پورتال برمی‌گردد و عنوانِ
// فیلد فرم (که پورتال از قبل ثبت کرده) سر جایش می‌ماند.
const prep = $('Prepare Prompt').first().json;
const res = $input.first().json;
const content = res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content;
const model = $env.LLM_CHAT_MODEL;
let result;
if (!content) {
  const err = res.error;
  const detail = (err && (err.message || (typeof err === 'string' ? err : JSON.stringify(err)))) || 'پاسخ خالی از مدل';
  result = { error: 'مدل زبانی پاسخ نداد؛ عنوان از فیلد «عنوان» فرم برداشته شد.', detail: String(detail).slice(0, 300), model };
} else {
  try {
    const clean = String(content).replace(/<think>[\s\S]*?<\/think>/g, '');
    const parsed = JSON.parse(clean.slice(clean.indexOf('{'), clean.lastIndexOf('}') + 1));
    result = {
      title_fa: String(parsed.title_fa || '').trim().slice(0, 250),
      title_en: String(parsed.title_en || '').trim().slice(0, 250),
      keywords: (Array.isArray(parsed.keywords) ? parsed.keywords : []).map((k) => String(k).trim()).filter(Boolean).slice(0, 8),
      model,
    };
    if (!result.title_fa) result = { error: 'مدل زبانی عنوانی برای پروژه پیدا نکرد.', model };
  } catch (e) {
    result = { error: 'خروجی مدل JSON معتبر نبود.', model };
  }
}
return [{ json: { result_path: prep.result_path, result } }];
